void abort(void);
void exit(int);

struct fd {
  unsigned char a;
  unsigned char b;
} f = {5};

struct fd *g() { return &f; }
int        h() { return -1; }

int main() {
  struct fd *f = g();
  f->b         = h();
  if (((f->a & 0x7f) & ~0x10) <= 2)
    abort();
  exit(0);
}


